    {
      "section id": "translator_gene_sets",
      "header": "CFDE gene sets that predict membership in your gene list",
      "data point": {
        "type": "openApi",
        "url": "https://translator.broadinstitute.org/genetics_provider/bayes_gene/gene_scores",
        "index": "huge",
        "parameters": [
          "genes"
        ],
        "parameters type": "string to array",
        "is value array": true,
        "data type": "object to array",
        "object": {
          "key": "Gene set",
          "value": "Marginal effect"
        },
        "header": {
          "Content-Type": "application/json"
        },
        "body": {
          "p_value": "0.05",
          "max_number_gene_sets": 150,
          "gene_sets": "cfde",
          "genes": "$genes"
        },
        "data wrapper": [
          "gene_set_scores"
        ]
      },
      "table format": {
        "initial sort by": {
          "field": "Marginal effect",
          "direction": "desc"
        },
        "data convert": [
          {
            "type": "raw",
            "field name": "Gene set",
            "raw field": "Gene set"
          },
          {
            "type": "raw",
            "field name": "Marginal effect",
            "raw field": "Marginal effect"
          },
          {
            "type": "translate to categories",
            "field name": "Evidence range (Marginal effect)",
            "raw field": "Marginal effect",
            "categories": [
              {
                "name": "Not Significant",
                "condition": "less than",
                "range": 0.01
              },
              {
                "name": "Significant",
                "condition": "and",
                "range": [
                  0.01,
                  0.1
                ]
              },
              {
                "name": "Strongly Significant",
                "condition": "and",
                "range": [
                  0.1,
                  1
                ]
              },
              {
                "name": "Extremely Significant",
                "condition": "greater than",
                "range": 1
              }
            ]
          },
          {
            "type": "raw",
            "field name": "Traits in which gene set affects genetic support",
            "raw field": "Gene set"
          }
        ],
        "top rows": [
          "Gene set",
          "Marginal effect",
          "Evidence range (Marginal effect)",
          "Traits in which gene set affects genetic support"
        ],
        "tool tips": {
          "Gene set": "Gene set identifier",
          "Marginal effect": "The marginal effect of a gene set measures its relevance to the phenotype when considered in isolation; this is the default measure by which the table is sorted and is the analog of traditional enrichment statistics. All gene set effects are expressed in units of log-odds of probabilities. Consider the following thresholds for interpreting marginal gene set effects: >0.01 = significant, >0.1 = strongly significant, and >1.0 = among the strongest for any phenotype and any gene set."
        },
        "column formatting": {
          "Marginal effect": {
            "type": [
              "scientific notation",
              "value in class"
            ]
          },
          "Traits in which gene set affects genetic support": {
            "type": [
              "dynamic subsection"
            ],
            "label": "Show",
            "subsection": {
              "data point": {
                "type": "bioindex",
                "url": "https://cfde-dev.hugeampkpnbi.org/api/bio/query/pigean-gene-set?q=$geneSet,cfde&limit=10000",
                "continue url": "https://cfde-dev.hugeampkpnbi.org/api/bio/cont?limit=10000&token=",
                "parameters": [
                  "geneSet"
                ],
                "parameters type": "replace",
                "data type": "bioindex"
              },
              "table format": {
                "data convert": [
                  {
                    "type": "map name",
                    "field name": "Phenotype",
                    "raw field": "phenotype",
                    "map": "shared resource",
                    "map name": "phenotype map"
                  },
                  {
                    "type": "map name",
                    "field name": "Phenotype name",
                    "raw field": "phenotype",
                    "map": "shared resource",
